var n=`1160-tacos-de-birria`;var o=`world-1160`;var a=`MX`;var t=`central-america-caribbean`;var s=8;var r=205;var d={en:`Tacos de Birria`,ua:`Такос із біррії`};var c={en:`Tacos de Birria is a dish from Mexico prepared with dried guajillo chilies, dried ancho chilies, garlic, yellow onion. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Такос із біррії, страва кухні країни Мексика, яку готують із таких продуктів: сушений перець гуахільйо, сушений перець анчо, часник, жовта цибуля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`dried-guajillo-chilies`,4,`pcs`],[`dried-ancho-chilies`,3,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`garlic`,6,`clove`],[`yellow-onion`,180,`g`],[`apple-cider-vinegar`,50,`ml`],[`ground-cumin`,6,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 170 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 170 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:170,i:[[`beef-chuck`,1100,`g`],[`beef-stock`,850,`ml`],[`ceylon-cinnamon`,1,`pcs`],[`ground-cloves`,4,`pcs`]]},{en:`Shred the fully cooked meat into thin pieces with clean forks, discarding bones and tough connective tissue.`,ua:`Розберіть повністю приготоване м’ясо чистими виделками на тонкі волокна, видаливши кістки й жорсткі частини.`,t:[`shredding`,`mixing`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 9 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 9 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:9,i:[[`corn-tortillas`,12,`pcs`],[`oaxaca-cheese`,210,`g`],[`canola-oil`,30,`ml`]]}];var u={slug:n,id:o,country:`MX`,region:t,servings:8,minutes:205,title:d,text:c,steps:l};export{a as country,u as default,o as id,r as minutes,t as region,s as servings,n as slug,l as steps,c as text,d as title};